# এসএসসি উচ্চতর গণিত অধ্যায় ১ (সেট ও ফাংশন), ২ (বীজগাণিতিক রাশি), ৩ (জ্যামিতি): প্রতি অনুশীলনী ৩০টি মধ্যম/কঠিন সংক্ষিপ্ত প্রশ্ন
from sqlib import *
from symchk import eq
import sympy as sp, math, itertools
x,y,a,b,c=sp.symbols('x y a b c'); cl=math.isclose; R=sp.Rational
P=lambda X,Y:{(p,q) for p in X for q in Y}
# ---- 1.1 ----
A=set(range(1,7)); B={1,2}; C={2,3}
assert A-(B|C)==(A-B)&(A-C)=={4,5,6} and A-(B&C)==(A-B)|(A-C)=={1,3,4,5,6} and 100-(60+45-25)==20 and 30+25-40==15
assert 100-(50+40+30-15-10-12+5)==12 and 12//3==4 and 2**12==4096 and P({1,2},{3,4}&{4,5})==P({1,2},{3,4})&P({1,2},{4,5})=={(1,4),(2,4)}
assert len(list(itertools.permutations('abc')))==6 and (5+3-2,5-2,(5-2)+(3-2))==(6,3,4)
A={'a','b'}; B={'b','c'}; assert P(A,B)-P(B,A)=={('a','b'),('a','c'),('b','c')} and math.comb(5,2)==10
assert 2**9==512 and 100-(70+60-40)==10 and {1,2,3,4}^{2,4,6,8}=={1,3,6,8} and (13+13-5)==21
