f=lambda e: sp.Lambda(x,e)
def inv(e): Y=sp.symbols('Y'); s=sp.solve(sp.Eq(Y,e),x); return sp.simplify(s[0].subs(Y,x))
assert sp.simplify(inv((2*x+1)/(x-1))-(x+1)/(x-2))==0 and inv(4*x+3).subs(x,11)==2 and sp.simplify(inv((x+2)/(x-3))-(3*x+2)/(x-1))==0
assert sp.simplify(inv((3*x-4)/(x-3))-(3*x-4)/(x-3))==0 and sp.simplify(((x-1)/(x+1)).subs(x,1/x)+(x-1)/(x+1))==0
g=(a*x+b)/(c*x-a); assert sp.simplify(g.subs(x,g)-x)==0
h=1/(1-x); assert sp.simplify(h.subs(x,h.subs(x,h))-x)==0
assert ((x**2+1).subs(x,2*2-3))==2 and 3**2==9 and math.perm(3,2)==6 and all((x**3-6*x**2+11*x-6).subs(x,v)==0 for v in (1,2,3))
assert sp.solve([a+b-5,-a+b-1],[a,b])=={a:2,b:3} and abs(-1-2)+abs(5-2)==6 and sorted(sp.solve(x**2-5*x+6-2,x))==[1,4]
assert sp.simplify((1+x)/(1-x)*(1-x)/(1+x))==1
