for l,r in [('2x³ + 3x² − 11x − 6','(x − 2)(2x + 1)(x + 3)'),('x⁴ − 5x³ + 5x² + 5x − 6','(x − 1)(x + 1)(x − 2)(x − 3)'),('a³ + b³ + c³ − 3abc','(a + b + c)(a² + b² + c² − ab − bc − ca)'),
 ('(b − c)³ + (c − a)³ + (a − b)³','3(a − b)(b − c)(c − a)'),('a²(b − c) + b²(c − a) + c²(a − b)','−(a − b)(b − c)(c − a)'),('bc(b − c) + ca(c − a) + ab(a − b)','−(a − b)(b − c)(c − a)'),
 ('x⁴ + 4y⁴','(x² + 2xy + 2y²)(x² − 2xy + 2y²)'),('6x² − 7xy − 3y²','(2x − 3y)(3x + y)'),('x³ − 7xy² − 6y³','(x + y)(x + 2y)(x − 3y)'),('(x + 1)(x + 2)(x + 3)(x + 4) − 24','x(x + 5)(x² + 5x + 10)'),
 ('a(b − c) + b(c − a) + c(a − b)','0'),('(x − 1)² + 5(x − 1) + 9','x² + 3x + 5'),('−2x³ + 5x² + x − 6','−(x + 1)(x − 2)(2x − 3)')]: eq(l,r)
