assert sp.apart(1/(x*(x+1)))==1/x-1/(x+1) and sp.apart((2*x+3)/(x-1)**2)==2/(x-1)+5/(x-1)**2 and sp.apart(x**2/((x-1)*(x-2)))==1-1/(x-1)+4/(x-2)
assert sp.simplify(sp.apart(1/((x-1)*(x**2+1)))-(1/(2*(x-1))-(x+1)/(2*(x**2+1))))==0 and sp.apart((3*x+1)/((x+1)*(x+2)*(x+3)))==-1/(x+1)+5/(x+2)-4/(x+3)
