assert 216-3*6*11+3*6==36 and 7*18-3==123 and sp.expand(sp.radsimp((sp.sqrt(3)+sp.sqrt(2))**2+1/(sp.sqrt(3)+sp.sqrt(2))**2))==10
assert sp.solve([1+a+b-3+2,1-a+b+3+2],[a,b])=={a:3,b:-3} and sp.Poly((2*x**2-3)*(x**3+1)).degree()==5
E2=[
("2x³ + 3x² − 11x − 6 কে উৎপাদকে বিশ্লেষণ কর।","P(2) = 0 ⇒ (x − 2) উৎপাদক; ভাগফল 2x² + 7x + 3 = (2x + 1)(x + 3)\n= (x − 2)(2x + 1)(x + 3)",'ক'),
("x⁴ + 2x³ − 3x + 1 কে (x + 2) দ্বারা ভাগ করলে ভাগশেষ নির্ণয় কর।","ভাগশেষ = P(−2) = 16 − 16 + 6 + 1 = 7",'ম'),
("ax³ + bx² + x − 6 রাশির দুইটি উৎপাদক (x + 1) ও (x − 2) হলে a ও b নির্ণয় কর।","P(−1) = 0 ⇒ −a + b = 7; P(2) = 0 ⇒ 2a + b = 1\n∴ a = −2, b = 5",'ক'),
("x⁴ − 5x³ + 5x² + 5x − 6 কে উৎপাদকে বিশ্লেষণ কর।","P(1) = P(−1) = P(2) = P(3) = 0\n= (x − 1)(x + 1)(x − 2)(x − 3)",'ক'),
("a³ + b³ + c³ − 3abc কে উৎপাদকে বিশ্লেষণ কর।","= (a + b)³ + c³ − 3ab(a + b + c) = (a + b + c)(a² + b² + c² − ab − bc − ca)",'ক'),
("a + b + c = 0 হলে প্রমাণ কর যে, a³ + b³ + c³ = 3abc","a³ + b³ + c³ − 3abc = (a + b + c)(…) = 0 ⇒ a³ + b³ + c³ = 3abc",'ম'),
("(b − c)³ + (c − a)³ + (a − b)³ কে উৎপাদকে বিশ্লেষণ কর।","তিনটি পদের যোগফল 0 ⇒ রাশি = 3(b − c)(c − a)(a − b)",'ক'),
("a²(b − c) + b²(c − a) + c²(a − b) কে উৎপাদকে বিশ্লেষণ কর।","a = b বসালে রাশি 0 ⇒ (a − b) উৎপাদক; চক্রক্রমে (b − c), (c − a)\n= −(a − b)(b − c)(c − a)",'ক'),
("bc(b − c) + ca(c − a) + ab(a − b) কে উৎপাদকে বিশ্লেষণ কর।","a = b বসালে 0 ⇒ (a − b), (b − c), (c − a) উৎপাদক; সহগ তুলনা করে\n= −(a − b)(b − c)(c − a)",'ক'),
("প্রতিসম ও চক্রক্রমিক রাশির পার্থক্য উদাহরণসহ লেখ।","a² + b² + c²: যেকোনো দুইটি চলক বিনিময়ে অপরিবর্তিত ⇒ প্রতিসম\na²b + b²c + c²a: শুধু a → b → c → a চক্রক্রমে অপরিবর্তিত ⇒ চক্রক্রমিক, প্রতিসম নয়",'ম'),
("a + b + c = 6, ab + bc + ca = 11 এবং abc = 6 হলে a³ + b³ + c³ এর মান নির্ণয় কর।","= (a + b + c)³ − 3(a + b + c)(ab + bc + ca) + 3abc = 216 − 198 + 18 = 36",'ক'),
("(5x − 1)/{(x − 1)(x + 1)} কে আংশিক ভগ্নাংশে প্রকাশ কর।","A/(x − 1) + B/(x + 1): x = 1 ⇒ A = 2; x = −1 ⇒ B = 3\n= 2/(x − 1) + 3/(x + 1)",'ম'),
("(x + 5)/(x² + x − 2) কে আংশিক ভগ্নাংশে প্রকাশ কর।","x² + x − 2 = (x − 1)(x + 2); x = 1 ⇒ A = 2; x = −2 ⇒ B = −1\n= 2/(x − 1) − 1/(x + 2)",'ক'),
("1/{x(x + 1)} কে আংশিক ভগ্নাংশে প্রকাশ কর।","= 1/x − 1/(x + 1)",'ম'),
("(2x + 3)/(x − 1)² কে আংশিক ভগ্নাংশে প্রকাশ কর।","2x + 3 = 2(x − 1) + 5\n= 2/(x − 1) + 5/(x − 1)²",'ক'),
("x²/{(x − 1)(x − 2)} কে আংশিক ভগ্নাংশে প্রকাশ কর।","অপ্রকৃত ভগ্নাংশ: = 1 + (3x − 2)/{(x − 1)(x − 2)}\n= 1 − 1/(x − 1) + 4/(x − 2)",'ক'),
("1/{(x − 1)(x² + 1)} কে আংশিক ভগ্নাংশে প্রকাশ কর।","A/(x − 1) + (Bx + C)/(x² + 1): A = 1/2, B = −1/2, C = −1/2\n= 1/{2(x − 1)} − (x + 1)/{2(x² + 1)}",'ক'),
("আংশিক ভগ্নাংশের সাহায্যে দেখাও যে, 1/(1·2) + 1/(2·3) + … + 1/{n(n + 1)} = n/(n + 1)","1/{k(k + 1)} = 1/k − 1/(k + 1); যোগ করলে মাঝের পদ কেটে যায়\n= 1 − 1/(n + 1) = n/(n + 1)",'ক'),
("x + 1/x = 3 হলে x⁵ + 1/x⁵ এর মান নির্ণয় কর।","x² + 1/x² = 7, x³ + 1/x³ = 18\nx⁵ + 1/x⁵ = (x² + 1/x²)(x³ + 1/x³) − (x + 1/x) = 126 − 3 = 123",'ক'),
("x = √3 + √2 হলে x² + 1/x² এর মান নির্ণয় কর।","1/x = √3 − √2 ⇒ x + 1/x = 2√3 ⇒ x² + 1/x² = 12 − 2 = 10",'ম'),
("(2x² − 3)(x³ + 1) বহুপদীর মাত্রা, মুখ্য সহগ ও ধ্রুবক পদ নির্ণয় কর।","= 2x⁵ − 3x³ + 2x² − 3\nমাত্রা 5, মুখ্য সহগ 2, ধ্রুবক পদ −3",'ম'),
("x² + 3x + 5 ≡ a(x − 1)² + b(x − 1) + c অভেদটিতে a, b, c এর মান নির্ণয় কর।","x = 1 ⇒ c = 9; x² এর সহগ ⇒ a = 1; x এর সহগ: −2a + b = 3 ⇒ b = 5",'ক'),
("x⁴ + 4y⁴ কে উৎপাদকে বিশ্লেষণ কর।","= (x² + 2y²)² − (2xy)² = (x² + 2xy + 2y²)(x² − 2xy + 2y²)",'ক'),
("x³ + 3x²y + y³ বহুপদীটি সমমাত্রিক কি না যাচাই কর।","প্রতিটি পদের মাত্রা 3 ⇒ সমমাত্রিক (মাত্রা 3)",'ম'),
("(x − 1) ও (x + 1) উভয়ই x⁴ + px³ + qx² − 3x + 2 এর উৎপাদক হলে p ও q নির্ণয় কর।","P(1) = 0 ⇒ p + q = 0; P(−1) = 0 ⇒ −p + q = −6\n∴ p = 3, q = −3",'ক'),
("6x² − 7xy − 3y² কে উৎপাদকে বিশ্লেষণ কর।","= 6x² − 9xy + 2xy − 3y² = (2x − 3y)(3x + y)",'ম'),
("x³ − 7xy² − 6y³ কে উৎপাদকে বিশ্লেষণ কর।","x = −y বসালে 0 ⇒ (x + y) উৎপাদক; ভাগফল x² − xy − 6y²\n= (x + y)(x + 2y)(x − 3y)",'ক'),
("(x + 1)(x + 2)(x + 3)(x + 4) − 24 কে উৎপাদকে বিশ্লেষণ কর।","= (x² + 5x + 4)(x² + 5x + 6) − 24; x² + 5x = p ⇒ p² + 10p = p(p + 10)\n= x(x + 5)(x² + 5x + 10)",'ক'),
("দেখাও যে, a(b − c) + b(c − a) + c(a − b) = 0","= ab − ac + bc − ab + ac − bc = 0",'ম'),
("(3x + 1)/{(x + 1)(x + 2)(x + 3)} কে আংশিক ভগ্নাংশে প্রকাশ কর।","x = −1 ⇒ A = −1; x = −2 ⇒ B = 5; x = −3 ⇒ C = −4\n= −1/(x + 1) + 5/(x + 2) − 4/(x + 3)",'ক'),
]
